def prefix_match(self, prefix):
    # Walk to prefix node
    node = self.root
    for char in prefix:
        if char not in node.children:
            return []
        node = node.children[char]

    # DFS to collect all words
    result = []
    def dfs(node, word):
        if node.isEndOfWord:
            result.append(word)
        for char, child in node.children.items():
            dfs(child, word + char)

    dfs(node, prefix)
    return result
